    "code": "class Solution {\n    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {\n        // Step 1: Build parent map\n        Map<TreeNode, TreeNode> parentMap = new HashMap<>();\n        buildParentMap(root, null, parentMap);\n\n        // Step 2: BFS from target for k levels\n        Queue<TreeNode> queue = new LinkedList<>();\n        Set<TreeNode> visited = new HashSet<>();\n        queue.offer(target);\n        visited.add(target);\n\n        int distance = 0;\n        while (!queue.isEmpty() && distance < k) {\n            int levelSize = queue.size();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n\n                // Expand to left child, right child, and parent\n                if (node.left != null && !visited.contains(node.left)) {\n                    visited.add(node.left);\n                    queue.offer(node.left);\n                }\n                if (node.right != null && !visited.contains(node.right)) {\n                    visited.add(node.right);\n                    queue.offer(node.right);\n                }\n                TreeNode parent = parentMap.get(node);\n                if (parent != null && !visited.contains(parent)) {\n                    visited.add(parent);\n                    queue.offer(parent);\n                }\n            }\n            distance++;\n        }\n\n        // Collect values from nodes at distance k\n        List<Integer> result = new ArrayList<>();\n        for (TreeNode node : queue) {\n            result.add(node.val);\n        }\n        return result;\n    }\n\n    private void buildParentMap(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {\n        if (node == null) return;\n        parentMap.put(node, parent);\n        buildParentMap(node.left, node, parentMap);\n        buildParentMap(node.right, node, parentMap);\n    }\n}",
