    "code": "public class Solution {\n    public IList<int> DistanceK(TreeNode root, TreeNode target, int k) {\n        Dictionary<TreeNode, TreeNode> parentMap = new Dictionary<TreeNode, TreeNode>();\n        BuildParentMap(root, null, parentMap);\n\n        Queue<TreeNode> queue = new Queue<TreeNode>();\n        HashSet<TreeNode> visited = new HashSet<TreeNode>();\n        queue.Enqueue(target);\n        visited.Add(target);\n\n        int distance = 0;\n        while (queue.Count > 0 && distance < k) {\n            int levelSize = queue.Count;\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.Dequeue();\n\n                if (node.left != null && !visited.Contains(node.left)) {\n                    visited.Add(node.left);\n                    queue.Enqueue(node.left);\n                }\n                if (node.right != null && !visited.Contains(node.right)) {\n                    visited.Add(node.right);\n                    queue.Enqueue(node.right);\n                }\n                TreeNode parent = parentMap.ContainsKey(node) ? parentMap[node] : null;\n                if (parent != null && !visited.Contains(parent)) {\n                    visited.Add(parent);\n                    queue.Enqueue(parent);\n                }\n            }\n            distance++;\n        }\n\n        IList<int> result = new List<int>();\n        foreach (TreeNode node in queue) {\n            result.Add(node.val);\n        }\n        return result;\n    }\n\n    private void BuildParentMap(TreeNode node, TreeNode parent, Dictionary<TreeNode, TreeNode> parentMap) {\n        if (node == null) return;\n        parentMap[node] = parent;\n        BuildParentMap(node.left, node, parentMap);\n        BuildParentMap(node.right, node, parentMap);\n    }\n}",
