    "code": "class Solution {\n    public int[] findOrder(int numCourses, int[][] prerequisites) {\n        // Build adjacency list\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n        for (int[] pre : prerequisites) {\n            graph.get(pre[1]).add(pre[0]);\n        }\n\n        // 0 = unvisited, 1 = in-progress, 2 = visited\n        int[] state = new int[numCourses];\n        List<Integer> order = new ArrayList<>();\n\n        for (int i = 0; i < numCourses; i++) {\n            if (state[i] == 0) {\n                if (!dfs(graph, i, state, order)) {\n                    return new int[0]; // Cycle detected\n                }\n            }\n        }\n\n        // Reverse the post-order to get topological order\n        int[] result = new int[numCourses];\n        for (int i = 0; i < numCourses; i++) {\n            result[i] = order.get(numCourses - 1 - i);\n        }\n        return result;\n    }\n\n    private boolean dfs(List<List<Integer>> graph, int node, int[] state, List<Integer> order) {\n        state[node] = 1; // Mark as in-progress\n        for (int neighbor : graph.get(node)) {\n            if (state[neighbor] == 1) return false; // Cycle: back edge found\n            if (state[neighbor] == 0) {\n                if (!dfs(graph, neighbor, state, order)) return false;\n            }\n        }\n        state[node] = 2; // Mark as visited\n        order.add(node); // Add to post-order\n        return true;\n    }\n}",
