    "code": "function findMinHeightTrees(n: number, edges: number[][]): number[] {\n    if (n === 1) return [0];\n    if (n === 2) return [0, 1];\n\n    // Build adjacency list and compute degrees\n    const adj: number[][] = Array.from({ length: n }, () => []);\n    const degree: number[] = new Array(n).fill(0);\n\n    for (const [u, v] of edges) {\n        adj[u].push(v);\n        adj[v].push(u);\n        degree[u]++;\n        degree[v]++;\n    }\n\n    // Collect initial leaves\n    let leaves: number[] = [];\n    for (let i = 0; i < n; i++) {\n        if (degree[i] === 1) leaves.push(i);\n    }\n\n    // Trim leaves layer by layer until 1 or 2 nodes remain\n    let remaining = n;\n    while (remaining > 2) {\n        remaining -= leaves.length;\n        const newLeaves: number[] = [];\n\n        for (const leaf of leaves) {\n            for (const neighbor of adj[leaf]) {\n                degree[neighbor]--;\n                if (degree[neighbor] === 1) {\n                    newLeaves.push(neighbor);\n                }\n            }\n        }\n\n        leaves = newLeaves;\n    }\n\n    return leaves;\n}",
