    "code": "class Solution {\n    public int[] sortItems(int n, int m, int[] group, List<List<Integer>> beforeItems) {\n        // Assign unique group IDs to ungrouped items\n        int totalGroups = m;\n        for (int i = 0; i < n; i++) {\n            if (group[i] == -1) {\n                group[i] = totalGroups++;\n            }\n        }\n\n        // Build item graph and group graph, and track group in-degrees\n        List<List<Integer>> itemGraph = new ArrayList<>();\n        List<List<Integer>> groupGraph = new ArrayList<>();\n        int[] groupInDegree = new int[totalGroups];\n\n        for (int i = 0; i < n; i++) itemGraph.add(new ArrayList<>());\n        for (int i = 0; i < totalGroups; i++) groupGraph.add(new ArrayList<>());\n\n        // Use a set to avoid duplicate group-level edges\n        Set<Long> groupEdgeSet = new HashSet<>();\n\n        for (int i = 0; i < n; i++) {\n            for (int prev : beforeItems.get(i)) {\n                // Item-level edge: prev -> i\n                itemGraph.get(prev).add(i);\n\n                // Group-level edge if different groups\n                if (group[prev] != group[i]) {\n                    long edgeKey = (long) group[prev] * totalGroups + group[i];\n                    if (groupEdgeSet.add(edgeKey)) {\n                        groupGraph.get(group[prev]).add(group[i]);\n                        groupInDegree[group[i]]++;\n                    }\n                }\n            }\n        }\n\n        // Topological sort on groups\n        List<Integer> groupOrder = topSort(groupGraph, groupInDegree, totalGroups);\n        if (groupOrder.isEmpty()) return new int[0];\n\n        // Bucket items by group\n        List<List<Integer>> groupMembers = new ArrayList<>();\n        for (int i = 0; i < totalGroups; i++) groupMembers.add(new ArrayList<>());\n        for (int i = 0; i < n; i++) groupMembers.get(group[i]).add(i);\n\n        // Sort items within each group and build result\n        List<Integer> result = new ArrayList<>();\n        for (int g : groupOrder) {\n            List<Integer> members = groupMembers.get(g);\n            if (members.isEmpty()) continue;\n\n            Set<Integer> memberSet = new HashSet<>(members);\n            Queue<Integer> queue = new LinkedList<>();\n\n            // Compute in-degree restricted to this group\n            int[] localInDegree = new int[n];\n            for (int item : members) {\n                for (int prev : beforeItems.get(item)) {\n                    if (memberSet.contains(prev)) {\n                        localInDegree[item]++;\n                    }\n                }\n            }\n\n            for (int item : members) {\n                if (localInDegree[item] == 0) queue.offer(item);\n            }\n\n            int count = 0;\n            while (!queue.isEmpty()) {\n                int item = queue.poll();\n                result.add(item);\n                count++;\n                for (int next : itemGraph.get(item)) {\n                    if (memberSet.contains(next)) {\n                        localInDegree[next]--;\n                        if (localInDegree[next] == 0) queue.offer(next);\n                    }\n                }\n            }\n\n            if (count != members.size()) return new int[0];\n        }\n\n        return result.stream().mapToInt(Integer::intValue).toArray();\n    }\n\n    private List<Integer> topSort(List<List<Integer>> graph, int[] inDegree, int count) {\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < count; i++) {\n            if (inDegree[i] == 0) queue.offer(i);\n        }\n\n        List<Integer> order = new ArrayList<>();\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            order.add(node);\n            for (int next : graph.get(node)) {\n                inDegree[next]--;\n                if (inDegree[next] == 0) queue.offer(next);\n            }\n        }\n\n        return order.size() == count ? order : new ArrayList<>();\n    }\n}",
