    "language": "cpp",
    "code": "class Solution {\npublic:\n    vector<int> sortItems(int n, int m, vector<int>& group, vector<vector<int>>& beforeItems) {\n        // Assign unique group IDs to ungrouped items\n        int totalGroups = m;\n        for (int i = 0; i < n; i++) {\n            if (group[i] == -1) {\n                group[i] = totalGroups++;\n            }\n        }\n\n        // Build item graph, group graph, and track in-degrees\n        vector<vector<int>> itemGraph(n), groupGraph(totalGroups);\n        vector<int> groupInDeg(totalGroups, 0);\n        set<pair<int,int>> groupEdgeSet;\n\n        for (int i = 0; i < n; i++) {\n            for (int prev : beforeItems[i]) {\n                itemGraph[prev].push_back(i);\n\n                if (group[prev] != group[i]) {\n                    auto edge = make_pair(group[prev], group[i]);\n                    if (groupEdgeSet.insert(edge).second) {\n                        groupGraph[group[prev]].push_back(group[i]);\n                        groupInDeg[group[i]]++;\n                    }\n                }\n            }\n        }\n\n        // Topological sort helper\n        auto topSort = [](vector<vector<int>>& graph, vector<int>& inDeg, int count) {\n            queue<int> q;\n            for (int i = 0; i < count; i++) {\n                if (inDeg[i] == 0) q.push(i);\n            }\n            vector<int> order;\n            while (!q.empty()) {\n                int node = q.front(); q.pop();\n                order.push_back(node);\n                for (int nxt : graph[node]) {\n                    if (--inDeg[nxt] == 0) q.push(nxt);\n                }\n            }\n            return (int)order.size() == count ? order : vector<int>();\n        };\n\n        // Topological sort on groups\n        vector<int> groupOrder = topSort(groupGraph, groupInDeg, totalGroups);\n        if (groupOrder.empty()) return {};\n\n        // Bucket items by group\n        vector<vector<int>> groupMembers(totalGroups);\n        for (int i = 0; i < n; i++) groupMembers[group[i]].push_back(i);\n\n        // Sort items within each group and build result\n        vector<int> result;\n        for (int g : groupOrder) {\n            auto& members = groupMembers[g];\n            if (members.empty()) continue;\n\n            unordered_set<int> memberSet(members.begin(), members.end());\n            vector<int> localInDeg(n, 0);\n\n            for (int item : members) {\n                for (int prev : beforeItems[item]) {\n                    if (memberSet.count(prev)) localInDeg[item]++;\n                }\n            }\n\n            queue<int> q;\n            for (int item : members) {\n                if (localInDeg[item] == 0) q.push(item);\n            }\n\n            int cnt = 0;\n            while (!q.empty()) {\n                int item = q.front(); q.pop();\n                result.push_back(item);\n                cnt++;\n                for (int nxt : itemGraph[item]) {\n                    if (memberSet.count(nxt)) {\n                        if (--localInDeg[nxt] == 0) q.push(nxt);\n                    }\n                }\n            }\n\n            if (cnt != (int)members.size()) return {};\n        }\n\n        return result;\n    }\n};",
