    "code": "var sortItems = function(n, m, group, beforeItems) {\n    // Assign unique group IDs to ungrouped items\n    let totalGroups = m;\n    for (let i = 0; i < n; i++) {\n        if (group[i] === -1) group[i] = totalGroups++;\n    }\n\n    // Build item graph, group graph, and track in-degrees\n    const itemGraph = Array.from({length: n}, () => []);\n    const groupGraph = Array.from({length: totalGroups}, () => []);\n    const groupInDegree = new Array(totalGroups).fill(0);\n    const groupEdgeSet = new Set();\n\n    for (let i = 0; i < n; i++) {\n        for (const prev of beforeItems[i]) {\n            itemGraph[prev].push(i);\n\n            if (group[prev] !== group[i]) {\n                const edgeKey = group[prev] * totalGroups + group[i];\n                if (!groupEdgeSet.has(edgeKey)) {\n                    groupEdgeSet.add(edgeKey);\n                    groupGraph[group[prev]].push(group[i]);\n                    groupInDegree[group[i]]++;\n                }\n            }\n        }\n    }\n\n    // Topological sort helper\n    const topSort = (graph, inDegree, count) => {\n        const queue = [];\n        for (let i = 0; i < count; i++) {\n            if (inDegree[i] === 0) queue.push(i);\n        }\n        const order = [];\n        let front = 0;\n        while (front < queue.length) {\n            const node = queue[front++];\n            order.push(node);\n            for (const nxt of graph[node]) {\n                if (--inDegree[nxt] === 0) queue.push(nxt);\n            }\n        }\n        return order.length === count ? order : [];\n    };\n\n    // Topological sort on groups\n    const groupOrder = topSort(groupGraph, groupInDegree, totalGroups);\n    if (groupOrder.length === 0) return [];\n\n    // Bucket items by group\n    const groupMembers = Array.from({length: totalGroups}, () => []);\n    for (let i = 0; i < n; i++) groupMembers[group[i]].push(i);\n\n    // Sort items within each group and build result\n    const result = [];\n    for (const g of groupOrder) {\n        const members = groupMembers[g];\n        if (members.length === 0) continue;\n\n        const memberSet = new Set(members);\n        const localInDegree = new Array(n).fill(0);\n\n        for (const item of members) {\n            for (const prev of beforeItems[item]) {\n                if (memberSet.has(prev)) localInDegree[item]++;\n            }\n        }\n\n        const queue = [];\n        for (const item of members) {\n            if (localInDegree[item] === 0) queue.push(item);\n        }\n\n        let front = 0;\n        let count = 0;\n        while (front < queue.length) {\n            const item = queue[front++];\n            result.push(item);\n            count++;\n            for (const nxt of itemGraph[item]) {\n                if (memberSet.has(nxt)) {\n                    if (--localInDegree[nxt] === 0) queue.push(nxt);\n                }\n            }\n        }\n\n        if (count !== members.length) return [];\n    }\n\n    return result;\n};",
