export function SortItemsByGroupsRespectingDependenciesProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: SortItemsByGroupsRespectingDependenciesTemplates,
      generateSteps: (e: any) => {
        const recorded = generateSortItemsByGroupsRespectingDependenciesSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Sort Items by Groups"
      slug="sort-items-by-groups-respecting-dependencies"
      approaches={approaches}
      presets={SortItemsByGroupsRespectingDependenciesPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

