    "code": "class Solution {\npublic:\n    string alienOrder(vector<string>& words) {\n        // Initialize adjacency list and in-degree for all characters\n        unordered_map<char, unordered_set<char>> adj;\n        unordered_map<char, int> inDegree;\n\n        for (auto& word : words) {\n            for (char c : word) {\n                adj[c];  // Ensure every character has an entry\n                inDegree[c] = 0;\n            }\n        }\n\n        // Compare adjacent words to extract ordering rules.\n        // i + 1 < words.size() avoids unsigned wraparound of size() - 1\n        for (size_t i = 0; i + 1 < words.size(); i++) {\n            string& word1 = words[i];\n            string& word2 = words[i + 1];\n            // Invalid case: \"abc\" before \"ab\"\n            if (word1.length() > word2.length() &&\n                word1.substr(0, word2.length()) == word2) {\n                return \"\";\n            }\n            size_t minLen = min(word1.length(), word2.length());\n            for (size_t j = 0; j < minLen; j++) {\n                char c1 = word1[j], c2 = word2[j];\n                if (c1 != c2) {\n                    // Only add edge if it does not already exist\n                    if (adj[c1].find(c2) == adj[c1].end()) {\n                        adj[c1].insert(c2);\n                        inDegree[c2]++;\n                    }\n                    break;  // Only first difference matters\n                }\n            }\n        }\n\n        // BFS topological sort (Kahn's algorithm)\n        queue<char> q;\n        for (auto& [c, deg] : inDegree) {\n            if (deg == 0) q.push(c);\n        }\n\n        string result;\n        while (!q.empty()) {\n            char c = q.front();\n            q.pop();\n            result += c;\n            for (char neighbor : adj[c]) {\n                if (--inDegree[neighbor] == 0) {\n                    q.push(neighbor);\n                }\n            }\n        }\n\n        // If result does not contain all characters, there is a cycle\n        return result.length() == inDegree.size() ? result : \"\";\n    }\n};",
