    "code": "public class Solution {\n    public string AlienOrder(string[] words) {\n        // Initialize adjacency list and in-degree for all characters\n        var adj = new Dictionary<char, HashSet<char>>();\n        var inDegree = new Dictionary<char, int>();\n\n        foreach (var word in words) {\n            foreach (var c in word) {\n                if (!adj.ContainsKey(c)) adj[c] = new HashSet<char>();\n                if (!inDegree.ContainsKey(c)) inDegree[c] = 0;\n            }\n        }\n\n        // Compare adjacent words to extract ordering rules\n        for (int i = 0; i < words.Length - 1; i++) {\n            string word1 = words[i], word2 = words[i + 1];\n            // Invalid case: \"abc\" before \"ab\"\n            if (word1.Length > word2.Length && word1.StartsWith(word2)) {\n                return \"\";\n            }\n            int minLen = Math.Min(word1.Length, word2.Length);\n            for (int j = 0; j < minLen; j++) {\n                char c1 = word1[j], c2 = word2[j];\n                if (c1 != c2) {\n                    // Only add edge if it does not already exist\n                    if (!adj[c1].Contains(c2)) {\n                        adj[c1].Add(c2);\n                        inDegree[c2] = inDegree[c2] + 1;\n                    }\n                    break;  // Only first difference matters\n                }\n            }\n        }\n\n        // BFS topological sort (Kahn's algorithm)\n        var queue = new Queue<char>();\n        foreach (var kvp in inDegree) {\n            if (kvp.Value == 0) queue.Enqueue(kvp.Key);\n        }\n\n        var result = new StringBuilder();\n        while (queue.Count > 0) {\n            char c = queue.Dequeue();\n            result.Append(c);\n            foreach (char neighbor in adj[c]) {\n                inDegree[neighbor]--;\n                if (inDegree[neighbor] == 0) queue.Enqueue(neighbor);\n            }\n        }\n\n        // If result does not contain all characters, there is a cycle\n        return result.Length == inDegree.Count ? result.ToString() : \"\";\n    }\n}",
