    "code": "func alienOrder(words []string) string {\n    // Initialize adjacency list and in-degree for all characters\n    adj := make(map[byte]map[byte]bool)\n    inDegree := make(map[byte]int)\n\n    for _, word := range words {\n        for i := 0; i < len(word); i++ {\n            if adj[word[i]] == nil {\n                adj[word[i]] = make(map[byte]bool)\n            }\n            if _, ok := inDegree[word[i]]; !ok {\n                inDegree[word[i]] = 0\n            }\n        }\n    }\n\n    // Compare adjacent words to extract ordering rules\n    for i := 0; i < len(words)-1; i++ {\n        word1, word2 := words[i], words[i+1]\n        // Invalid case: \"abc\" before \"ab\"\n        if len(word1) > len(word2) && word1[:len(word2)] == word2 {\n            return \"\"\n        }\n        minLen := len(word1)\n        if len(word2) < minLen {\n            minLen = len(word2)\n        }\n        for j := 0; j < minLen; j++ {\n            c1, c2 := word1[j], word2[j]\n            if c1 != c2 {\n                // Only add edge if it does not already exist\n                if !adj[c1][c2] {\n                    adj[c1][c2] = true\n                    inDegree[c2]++\n                }\n                break // Only first difference matters\n            }\n        }\n    }\n\n    // BFS topological sort (Kahn's algorithm)\n    queue := []byte{}\n    for c := range inDegree {\n        if inDegree[c] == 0 {\n            queue = append(queue, c)\n        }\n    }\n\n    result := []byte{}\n    for len(queue) > 0 {\n        c := queue[0]\n        queue = queue[1:]\n        result = append(result, c)\n        for neighbor := range adj[c] {\n            inDegree[neighbor]--\n            if inDegree[neighbor] == 0 {\n                queue = append(queue, neighbor)\n            }\n        }\n    }\n\n    // If result does not contain all characters, there is a cycle\n    if len(result) != len(inDegree) {\n        return \"\"\n    }\n    return string(result)\n}",
