    "code": "public class Solution {\n    public double[] CalcEquation(IList<IList<string>> equations, double[] values, IList<IList<string>> queries) {\n        // Build adjacency list\n        var graph = new Dictionary<string, List<(string neighbor, double weight)>>();\n\n        for (int i = 0; i < equations.Count; i++) {\n            string a = equations[i][0], b = equations[i][1];\n            if (!graph.ContainsKey(a)) graph[a] = new List<(string, double)>();\n            if (!graph.ContainsKey(b)) graph[b] = new List<(string, double)>();\n            graph[a].Add((b, values[i]));\n            graph[b].Add((a, 1.0 / values[i]));\n        }\n\n        double[] results = new double[queries.Count];\n        for (int q = 0; q < queries.Count; q++) {\n            results[q] = Bfs(queries[q][0], queries[q][1], graph);\n        }\n        return results;\n    }\n\n    private double Bfs(string source, string target,\n                       Dictionary<string, List<(string neighbor, double weight)>> graph) {\n        if (!graph.ContainsKey(source) || !graph.ContainsKey(target)) return -1.0;\n        if (source == target) return 1.0;\n\n        var queue = new Queue<(string node, double product)>();\n        var visited = new HashSet<string>();\n        queue.Enqueue((source, 1.0));\n        visited.Add(source);\n\n        while (queue.Count > 0) {\n            var (node, product) = queue.Dequeue();\n            foreach (var (neighbor, weight) in graph[node]) {\n                if (neighbor == target) return product * weight;\n                if (!visited.Contains(neighbor)) {\n                    visited.Add(neighbor);\n                    queue.Enqueue((neighbor, product * weight));\n                }\n            }\n        }\n        return -1.0;\n    }\n}",
