    "code": "func calcEquation(equations [][]string, values []float64, queries [][]string) []float64 {\n    // Build adjacency list\n    type edge struct {\n        neighbor string\n        weight   float64\n    }\n    graph := make(map[string][]edge)\n\n    for i, eq := range equations {\n        a, b := eq[0], eq[1]\n        graph[a] = append(graph[a], edge{b, values[i]})\n        graph[b] = append(graph[b], edge{a, 1.0 / values[i]})\n    }\n\n    bfs := func(source, target string) float64 {\n        if _, ok := graph[source]; !ok {\n            return -1.0\n        }\n        if _, ok := graph[target]; !ok {\n            return -1.0\n        }\n        if source == target {\n            return 1.0\n        }\n\n        type item struct {\n            node    string\n            product float64\n        }\n        queue := []item{{source, 1.0}}\n        visited := map[string]bool{source: true}\n\n        for len(queue) > 0 {\n            curr := queue[0]\n            queue = queue[1:]\n\n            for _, e := range graph[curr.node] {\n                if e.neighbor == target {\n                    return curr.product * e.weight\n                }\n                if !visited[e.neighbor] {\n                    visited[e.neighbor] = true\n                    queue = append(queue, item{e.neighbor, curr.product * e.weight})\n                }\n            }\n        }\n        return -1.0\n    }\n\n    results := make([]float64, len(queries))\n    for i, q := range queries {\n        results[i] = bfs(q[0], q[1])\n    }\n    return results\n}",
