    "code": "class Solution {\n    private int timer = 0;\n    private List<List<Integer>> result = new ArrayList<>();\n\n    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {\n        // Build adjacency list\n        List<List<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());\n\n        for (List<Integer> conn : connections) {\n            adj.get(conn.get(0)).add(conn.get(1));\n            adj.get(conn.get(1)).add(conn.get(0));\n        }\n\n        int[] disc = new int[n];\n        int[] low = new int[n];\n        Arrays.fill(disc, -1); // -1 means unvisited\n\n        dfs(0, -1, adj, disc, low);\n\n        return result;\n    }\n\n    private void dfs(int u, int parent, List<List<Integer>> adj, int[] disc, int[] low) {\n        disc[u] = low[u] = timer++;\n\n        for (int v : adj.get(u)) {\n            if (v == parent) continue; // skip the edge back to parent\n            if (disc[v] == -1) {\n                // Tree edge: v is unvisited\n                dfs(v, u, adj, disc, low);\n                low[u] = Math.min(low[u], low[v]);\n                // If v cannot reach u or above, edge (u,v) is a bridge\n                if (low[v] > disc[u]) {\n                    result.add(Arrays.asList(u, v));\n                }\n            } else {\n                // Back edge: v is already visited\n                low[u] = Math.min(low[u], disc[v]);\n            }\n        }\n    }\n}",
