    "code": "func criticalConnections(n int, connections [][]int) [][]int {\n    // Build adjacency list\n    adj := make([][]int, n)\n    for _, conn := range connections {\n        adj[conn[0]] = append(adj[conn[0]], conn[1])\n        adj[conn[1]] = append(adj[conn[1]], conn[0])\n    }\n\n    disc := make([]int, n)\n    low := make([]int, n)\n    for i := range disc {\n        disc[i] = -1 // -1 means unvisited\n    }\n\n    timer := 0\n    result := [][]int{}\n\n    var dfs func(u, parent int)\n    dfs = func(u, parent int) {\n        disc[u] = timer\n        low[u] = timer\n        timer++\n\n        for _, v := range adj[u] {\n            if v == parent {\n                continue // skip edge back to parent\n            }\n            if disc[v] == -1 {\n                // Tree edge: v is unvisited\n                dfs(v, u)\n                if low[v] < low[u] {\n                    low[u] = low[v]\n                }\n                // If v cannot reach u or above, edge is a bridge\n                if low[v] > disc[u] {\n                    result = append(result, []int{u, v})\n                }\n            } else {\n                // Back edge: v is already visited\n                if disc[v] < low[u] {\n                    low[u] = disc[v]\n                }\n            }\n        }\n    }\n\n    dfs(0, -1)\n    return result\n}",
