export function CriticalConnectionsInANetworkProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: CriticalConnectionsInANetworkTemplates,
      generateSteps: (e: any) => {
        const recorded = generateCriticalConnectionsInANetworkSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Critical Connections in a Network"
      slug="critical-connections-in-a-network"
      approaches={approaches}
      presets={CriticalConnectionsInANetworkPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

