    "code": "class Solution {\n    public int minMutation(String startGene, String endGene, String[] bank) {\n        if (startGene.equals(endGene)) return 0;\n\n        Set<String> bankSet = new HashSet<>();\n        for (String gene : bank) {\n            bankSet.add(gene);\n        }\n        if (!bankSet.contains(endGene)) return -1;\n\n        char[] chars = {'A', 'C', 'G', 'T'};\n        Queue<String> queue = new LinkedList<>();\n        Set<String> visited = new HashSet<>();\n        queue.offer(startGene);\n        visited.add(startGene);\n        int mutations = 0;\n\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                String current = queue.poll();\n                char[] currentArr = current.toCharArray();\n\n                // Try mutating each position to each possible character\n                for (int j = 0; j < 8; j++) {\n                    char original = currentArr[j];\n                    for (char c : chars) {\n                        if (c == original) continue;\n                        currentArr[j] = c;\n                        String mutated = new String(currentArr);\n\n                        if (bankSet.contains(mutated) && !visited.contains(mutated)) {\n                            if (mutated.equals(endGene)) return mutations + 1;\n                            queue.offer(mutated);\n                            visited.add(mutated);\n                        }\n                    }\n                    currentArr[j] = original; // restore original character\n                }\n            }\n            mutations++;\n        }\n        return -1;\n    }\n}",
