    "code": "public class Solution {\n    public int MinMutation(string startGene, string endGene, string[] bank) {\n        if (startGene == endGene) return 0;\n\n        HashSet<string> bankSet = new HashSet<string>(bank);\n        if (!bankSet.Contains(endGene)) return -1;\n\n        char[] chars = {'A', 'C', 'G', 'T'};\n        Queue<string> queue = new Queue<string>();\n        HashSet<string> visited = new HashSet<string>();\n        queue.Enqueue(startGene);\n        visited.Add(startGene);\n        int mutations = 0;\n\n        while (queue.Count > 0) {\n            int size = queue.Count;\n            for (int i = 0; i < size; i++) {\n                char[] current = queue.Dequeue().ToCharArray();\n\n                // Try mutating each position to each possible character\n                for (int j = 0; j < 8; j++) {\n                    char original = current[j];\n                    foreach (char c in chars) {\n                        if (c == original) continue;\n                        current[j] = c;\n                        string mutated = new string(current);\n\n                        if (bankSet.Contains(mutated) && !visited.Contains(mutated)) {\n                            if (mutated == endGene) return mutations + 1;\n                            queue.Enqueue(mutated);\n                            visited.Add(mutated);\n                        }\n                    }\n                    current[j] = original; // restore original character\n                }\n            }\n            mutations++;\n        }\n        return -1;\n    }\n}",
