    "code": "public class Solution {\n    public int NumBusesToDestination(int[][] routes, int source, int target) {\n        if (source == target) return 0;\n\n        int n = routes.Length;\n        // Map each stop to the routes that serve it\n        var stopToRoutes = new Dictionary<int, List<int>>();\n        for (int i = 0; i < n; i++) {\n            foreach (int stop in routes[i]) {\n                if (!stopToRoutes.ContainsKey(stop))\n                    stopToRoutes[stop] = new List<int>();\n                stopToRoutes[stop].Add(i);\n            }\n        }\n\n        // Identify routes containing the target\n        var targetRoutes = new HashSet<int>();\n        if (stopToRoutes.ContainsKey(target)) {\n            foreach (int r in stopToRoutes[target]) targetRoutes.Add(r);\n        }\n\n        // BFS on routes, starting from all routes that serve the source\n        var queue = new Queue<int>();\n        var visitedRoutes = new bool[n];\n        if (stopToRoutes.ContainsKey(source)) {\n            foreach (int route in stopToRoutes[source]) {\n                queue.Enqueue(route);\n                visitedRoutes[route] = true;\n            }\n        }\n\n        int buses = 1;\n        while (queue.Count > 0) {\n            int size = queue.Count;\n            for (int i = 0; i < size; i++) {\n                int route = queue.Dequeue();\n                if (targetRoutes.Contains(route)) return buses;\n                foreach (int stop in routes[route]) {\n                    if (!stopToRoutes.ContainsKey(stop)) continue;\n                    foreach (int neighbor in stopToRoutes[stop]) {\n                        if (!visitedRoutes[neighbor]) {\n                            visitedRoutes[neighbor] = true;\n                            queue.Enqueue(neighbor);\n                        }\n                    }\n                }\n            }\n            buses++;\n        }\n        return -1;\n    }\n}",
