    "code": "func minimumObstacles(grid [][]int) int {\n    m, n := len(grid), len(grid[0])\n    dist := make([][]int, m)\n    for i := range dist {\n        dist[i] = make([]int, n)\n        for j := range dist[i] {\n            dist[i][j] = math.MaxInt32\n        }\n    }\n    dist[0][0] = 0\n\n    // Min-heap: {cost, row, col}\n    h := &minHeap{{0, 0, 0}}\n    heap.Init(h)\n\n    dirs := [4][2]int{{0,1},{0,-1},{1,0},{-1,0}}\n\n    for h.Len() > 0 {\n        curr := heap.Pop(h).([3]int)\n        cost, r, c := curr[0], curr[1], curr[2]\n\n        if r == m-1 && c == n-1 {\n            return cost\n        }\n        if cost > dist[r][c] {\n            continue\n        }\n\n        for _, d := range dirs {\n            nr, nc := r+d[0], c+d[1]\n            if nr >= 0 && nr < m && nc >= 0 && nc < n {\n                newCost := cost + grid[nr][nc]\n                if newCost < dist[nr][nc] {\n                    dist[nr][nc] = newCost\n                    heap.Push(h, [3]int{newCost, nr, nc})\n                }\n            }\n        }\n    }\n\n    return dist[m-1][n-1]\n}\n\ntype minHeap [][3]int\nfunc (h minHeap) Len() int            { return len(h) }\nfunc (h minHeap) Less(i, j int) bool   { return h[i][0] < h[j][0] }\nfunc (h minHeap) Swap(i, j int)        { h[i], h[j] = h[j], h[i] }\nfunc (h *minHeap) Push(x interface{})  { *h = append(*h, x.([3]int)) }\nfunc (h *minHeap) Pop() interface{} {\n    old := *h\n    val := old[len(old)-1]\n    *h = old[:len(old)-1]\n    return val\n}",
