    "code": "class Solution {\n    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {\n        // Build adjacency list\n        List<int[]>[] graph = new List[n];\n        for (int i = 0; i < n; i++) {\n            graph[i] = new ArrayList<>();\n        }\n        for (int[] flight : flights) {\n            graph[flight[0]].add(new int[]{flight[1], flight[2]});\n        }\n\n        int[] dist = new int[n];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[src] = 0;\n\n        List<Integer> frontier = new ArrayList<>();\n        frontier.add(src);\n\n        // Process at most k + 1 levels\n        for (int level = 0; level <= k && !frontier.isEmpty(); level++) {\n            // Reads use dist (previous level); writes go to tempDist\n            int[] tempDist = dist.clone();\n            List<Integer> nextFrontier = new ArrayList<>();\n            boolean[] queued = new boolean[n];\n\n            for (int city : frontier) {\n                for (int[] neighbor : graph[city]) {\n                    int next = neighbor[0];\n                    int newCost = dist[city] + neighbor[1];\n\n                    if (newCost < tempDist[next]) {\n                        tempDist[next] = newCost;\n                        // Each city enters the next frontier once per level\n                        if (!queued[next]) {\n                            queued[next] = true;\n                            nextFrontier.add(next);\n                        }\n                    }\n                }\n            }\n            dist = tempDist;\n            frontier = nextFrontier;\n        }\n\n        return dist[dst] == Integer.MAX_VALUE ? -1 : dist[dst];\n    }\n}",
