    "code": "public class Solution {\n    public long MinimumWeight(int n, int[][] edges, int src1, int src2, int dest) {\n        var graph = new List<(int to, long weight)>[n];\n        for (int i = 0; i < n; i++) graph[i] = new List<(int, long)>();\n        foreach (var e in edges) {\n            graph[e[0]].Add((e[1], e[2]));\n        }\n\n        var dist1 = Dijkstra(graph, src1, n);\n        var dist2 = Dijkstra(graph, src2, n);\n\n        long ans = long.MaxValue;\n        for (int m = 0; m < n; m++) {\n            if (dist1[m] == long.MaxValue || dist2[m] == long.MaxValue) continue;\n            var distM = Dijkstra(graph, m, n);\n            if (distM[dest] == long.MaxValue) continue;\n            ans = Math.Min(ans, dist1[m] + dist2[m] + distM[dest]);\n        }\n        return ans == long.MaxValue ? -1 : ans;\n    }\n\n    private long[] Dijkstra(List<(int to, long weight)>[] graph, int src, int n) {\n        var dist = new long[n];\n        Array.Fill(dist, long.MaxValue);\n        dist[src] = 0;\n        var pq = new PriorityQueue<int, long>();\n        pq.Enqueue(src, 0);\n        while (pq.Count > 0) {\n            int u = pq.Dequeue();\n            foreach (var (v, w) in graph[u]) {\n                if (dist[u] != long.MaxValue && dist[u] + w < dist[v]) {\n                    dist[v] = dist[u] + w;\n                    pq.Enqueue(v, dist[v]);\n                }\n            }\n        }\n        return dist;\n    }\n}",
