    "code": "func minimumWeight(n int, edges [][]int, src1 int, src2 int, dest int) int64 {\n    graph := make([][][2]int64, n)\n    for _, e := range edges {\n        graph[e[0]] = append(graph[e[0]], [2]int64{int64(e[1]), int64(e[2])})\n    }\n\n    dijkstra := func(src int) []int64 {\n        dist := make([]int64, n)\n        for i := range dist {\n            dist[i] = math.MaxInt64\n        }\n        dist[src] = 0\n        pq := &minHeap{{0, int64(src)}}\n        heap.Init(pq)\n        for pq.Len() > 0 {\n            curr := heap.Pop(pq).([2]int64)\n            d, u := curr[0], int(curr[1])\n            if d > dist[u] {\n                continue\n            }\n            for _, edge := range graph[u] {\n                v, w := int(edge[0]), edge[1]\n                if dist[u]+w < dist[v] {\n                    dist[v] = dist[u] + w\n                    heap.Push(pq, [2]int64{dist[v], int64(v)})\n                }\n            }\n        }\n        return dist\n    }\n\n    dist1 := dijkstra(src1)\n    dist2 := dijkstra(src2)\n\n    var ans int64 = math.MaxInt64\n    for m := 0; m < n; m++ {\n        if dist1[m] == math.MaxInt64 || dist2[m] == math.MaxInt64 {\n            continue\n        }\n        distM := dijkstra(m)\n        if distM[dest] == math.MaxInt64 {\n            continue\n        }\n        total := dist1[m] + dist2[m] + distM[dest]\n        if total < ans {\n            ans = total\n        }\n    }\n    if ans == math.MaxInt64 {\n        return -1\n    }\n    return ans\n}\n\ntype minHeap [][2]int64\nfunc (h minHeap) Len() int            { return len(h) }\nfunc (h minHeap) Less(i, j int) bool   { return h[i][0] < h[j][0] }\nfunc (h minHeap) Swap(i, j int)        { h[i], h[j] = h[j], h[i] }\nfunc (h *minHeap) Push(x interface{})  { *h = append(*h, x.([2]int64)) }\nfunc (h *minHeap) Pop() interface{} {\n    old := *h\n    n := len(old)\n    x := old[n-1]\n    *h = old[:n-1]\n    return x\n}",
