export function MinimumWeightedSubgraphWithTheRequiredPathsProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: MinimumWeightedSubgraphWithTheRequiredPathsTemplates,
      generateSteps: (e: any) => {
        const recorded = generateMinimumWeightedSubgraphWithTheRequiredPathsSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Minimum Weighted Subgraph With the Required Paths"
      slug="minimum-weighted-subgraph-with-the-required-paths"
      approaches={approaches}
      presets={MinimumWeightedSubgraphWithTheRequiredPathsPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

