    "code": "func minCostConnectPoints(points [][]int) int {\n    n := len(points)\n    parent := make([]int, n)\n    rnk := make([]int, n)\n    for i := range parent {\n        parent[i] = i\n    }\n\n    var find func(int) int\n    find = func(x int) int {\n        if parent[x] != x {\n            parent[x] = find(parent[x])\n        }\n        return parent[x]\n    }\n\n    union := func(x, y int) {\n        px, py := find(x), find(y)\n        if rnk[px] < rnk[py] {\n            px, py = py, px\n        }\n        parent[py] = px\n        if rnk[px] == rnk[py] {\n            rnk[px]++\n        }\n    }\n\n    // Generate all edges\n    type edge struct{ cost, u, v int }\n    edges := make([]edge, 0)\n    for i := 0; i < n; i++ {\n        for j := i + 1; j < n; j++ {\n            cost := abs(points[i][0]-points[j][0]) + abs(points[i][1]-points[j][1])\n            edges = append(edges, edge{cost, i, j})\n        }\n    }\n\n    // Sort edges by cost\n    sort.Slice(edges, func(i, j int) bool {\n        return edges[i].cost < edges[j].cost\n    })\n\n    totalCost := 0\n    edgesUsed := 0\n    for _, e := range edges {\n        if edgesUsed == n-1 {\n            break\n        }\n        // If u and v are in different components, merge them\n        if find(e.u) != find(e.v) {\n            union(e.u, e.v)\n            totalCost += e.cost\n            edgesUsed++\n        }\n    }\n    return totalCost\n}\n\nfunc abs(x int) int {\n    if x < 0 {\n        return -x\n    }\n    return x\n}",
