export function ConnectingCitiesWithMinimumCostProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: ConnectingCitiesWithMinimumCostTemplates,
      generateSteps: (t: any) => {
        const recorded = generateConnectingCitiesWithMinimumCostSteps(t) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Connecting Cities With Minimum Cost"
      slug="connecting-cities-with-minimum-cost"
      approaches={approaches}
      presets={ConnectingCitiesWithMinimumCostPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

