export function OptimizeWaterDistributionInAVillageProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: OptimizeWaterDistributionInAVillageTemplates,
      generateSteps: (e: any) => {
        const recorded = generateOptimizeWaterDistributionInAVillageSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Optimize Water Distribution in a Village"
      slug="optimize-water-distribution-in-a-village"
      approaches={approaches}
      presets={OptimizeWaterDistributionInAVillagePresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

