    "code": "public List<(int, int)> AStar(int rows, int cols, (int, int) start,\n                              (int, int) end, List<(int, int)> obstacles) {\n    var obstacleSet = new HashSet<string>(\n        obstacles.Select(o => $\"{o.Item1},{o.Item2}\"));\n\n    int Heuristic(int r, int c) =>\n        Math.Abs(r - end.Item1) + Math.Abs(c - end.Item2);\n\n    // Open set: (f, g, row, col)\n    var openSet = new PriorityQueue<(int g, int row, int col), int>();\n    int startH = Heuristic(start.Item1, start.Item2);\n    openSet.Enqueue((0, start.Item1, start.Item2), startH);\n\n    var gScore = new Dictionary<string, int> {\n        [$\"{start.Item1},{start.Item2}\"] = 0\n    };\n    var cameFrom = new Dictionary<string, (int, int)>();\n    var closedSet = new HashSet<string>();\n\n    int[][] dirs = { new[]{-1,0}, new[]{1,0}, new[]{0,-1}, new[]{0,1} };\n\n    while (openSet.Count > 0) {\n        var (g, row, col) = openSet.Dequeue();\n        string key = $\"{row},{col}\";\n\n        if (closedSet.Contains(key)) continue;\n        closedSet.Add(key);\n\n        if (row == end.Item1 && col == end.Item2) {\n            // Reconstruct path\n            var path = new List<(int, int)>();\n            var curr = key;\n            while (cameFrom.ContainsKey(curr)) {\n                var parts = curr.Split(',');\n                path.Add((int.Parse(parts[0]), int.Parse(parts[1])));\n                var (pr, pc) = cameFrom[curr];\n                curr = $\"{pr},{pc}\";\n            }\n            path.Add(start);\n            path.Reverse();\n            return path;\n        }\n\n        foreach (var d in dirs) {\n            int nr = row + d[0], nc = col + d[1];\n            string nKey = $\"{nr},{nc}\";\n            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&\n                !obstacleSet.Contains(nKey) && !closedSet.Contains(nKey)) {\n                int newG = g + 1;\n                if (!gScore.ContainsKey(nKey) || newG < gScore[nKey]) {\n                    gScore[nKey] = newG;\n                    cameFrom[nKey] = (row, col);\n                    openSet.Enqueue((newG, nr, nc), newG + Heuristic(nr, nc));\n                }\n            }\n        }\n    }\n\n    return new List<(int, int)>();  // No path\n}",
