    "code": "func aStar(rows, cols int, start, end [2]int, obstacles [][2]int) [][2]int {\n    obstacleSet := make(map[string]bool)\n    for _, o := range obstacles {\n        obstacleSet[fmt.Sprintf(\"%d,%d\", o[0], o[1])] = true\n    }\n\n    heuristic := func(r, c int) int {\n        return abs(r-end[0]) + abs(c-end[1])\n    }\n\n    // Open set: (f, g, row, col)\n    openSet := &MinHeap{}\n    startH := heuristic(start[0], start[1])\n    heap.Push(openSet, [4]int{startH, 0, start[0], start[1]})\n\n    gScore := map[string]int{fmt.Sprintf(\"%d,%d\", start[0], start[1]): 0}\n    cameFrom := map[string][2]int{}\n    closedSet := map[string]bool{}\n\n    dirs := [][2]int{{-1,0},{1,0},{0,-1},{0,1}}\n\n    for openSet.Len() > 0 {\n        curr := heap.Pop(openSet).([4]int)\n        f, g, row, col := curr[0], curr[1], curr[2], curr[3]\n        key := fmt.Sprintf(\"%d,%d\", row, col)\n\n        if closedSet[key] { continue }\n        closedSet[key] = true\n\n        if row == end[0] && col == end[1] {\n            // Reconstruct path\n            path := [][2]int{}\n            c := key\n            for _, ok := cameFrom[c]; ok; _, ok = cameFrom[c] {\n                parts := strings.Split(c, \",\")\n                r, _ := strconv.Atoi(parts[0])\n                cl, _ := strconv.Atoi(parts[1])\n                path = append(path, [2]int{r, cl})\n                prev := cameFrom[c]\n                c = fmt.Sprintf(\"%d,%d\", prev[0], prev[1])\n            }\n            path = append(path, start)\n            // Reverse\n            for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {\n                path[i], path[j] = path[j], path[i]\n            }\n            return path\n        }\n\n        for _, d := range dirs {\n            nr, nc := row+d[0], col+d[1]\n            nKey := fmt.Sprintf(\"%d,%d\", nr, nc)\n            if nr >= 0 && nr < rows && nc >= 0 && nc < cols &&\n                !obstacleSet[nKey] && !closedSet[nKey] {\n                newG := g + 1\n                if prev, ok := gScore[nKey]; !ok || newG < prev {\n                    gScore[nKey] = newG\n                    cameFrom[nKey] = [2]int{row, col}\n                    heap.Push(openSet, [4]int{newG+heuristic(nr,nc), newG, nr, nc})\n                }\n            }\n        }\n    }\n\n    return nil  // No path\n}",
