    "code": "class Solution {\n    public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {\n        int e = edges.length;\n        // Attach original index to each edge\n        int[][] indexedEdges = new int[e][4];\n        for (int i = 0; i < e; i++) {\n            indexedEdges[i] = new int[]{edges[i][0], edges[i][1], edges[i][2], i};\n        }\n        // Sort by weight\n        Arrays.sort(indexedEdges, (a, b) -> a[2] - b[2]);\n\n        // Compute baseline MST weight\n        int baselineWeight = buildMST(n, indexedEdges, -1, -1);\n\n        List<Integer> critical = new ArrayList<>();\n        List<Integer> pseudoCritical = new ArrayList<>();\n\n        for (int i = 0; i < e; i++) {\n            // Exclusion test: build MST without edge i\n            int weightWithout = buildMST(n, indexedEdges, i, -1);\n            if (weightWithout > baselineWeight) {\n                critical.add(indexedEdges[i][3]);\n            } else {\n                // Inclusion test: force-include edge i, then build rest\n                int weightWith = buildMST(n, indexedEdges, -1, i);\n                if (weightWith == baselineWeight) {\n                    pseudoCritical.add(indexedEdges[i][3]);\n                }\n            }\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        result.add(critical);\n        result.add(pseudoCritical);\n        return result;\n    }\n\n    // Build MST, optionally excluding one edge and/or force-including another\n    // Returns MST weight or Integer.MAX_VALUE if graph is disconnected\n    private int buildMST(int n, int[][] edges, int excludeIdx, int includeIdx) {\n        int[] parent = new int[n];\n        int[] rank = new int[n];\n        for (int i = 0; i < n; i++) parent[i] = i;\n\n        int weight = 0;\n        int edgesUsed = 0;\n\n        // Force-include the specified edge first\n        if (includeIdx >= 0) {\n            weight += edges[includeIdx][2];\n            union(parent, rank, find(parent, edges[includeIdx][0]), find(parent, edges[includeIdx][1]));\n            edgesUsed++;\n        }\n\n        // Run Kruskal's on remaining edges\n        for (int i = 0; i < edges.length; i++) {\n            if (i == excludeIdx || i == includeIdx) continue;\n            int u = edges[i][0], v = edges[i][1], w = edges[i][2];\n            int pu = find(parent, u), pv = find(parent, v);\n            if (pu != pv) {\n                union(parent, rank, pu, pv);\n                weight += w;\n                edgesUsed++;\n                if (edgesUsed == n - 1) break;\n            }\n        }\n\n        return edgesUsed == n - 1 ? weight : Integer.MAX_VALUE;\n    }\n\n    private int find(int[] parent, int x) {\n        if (parent[x] != x) parent[x] = find(parent, parent[x]);\n        return parent[x];\n    }\n\n    private void union(int[] parent, int[] rank, int x, int y) {\n        if (rank[x] < rank[y]) parent[x] = y;\n        else if (rank[x] > rank[y]) parent[y] = x;\n        else { parent[y] = x; rank[x]++; }\n    }\n}",
