    "code": "function findCriticalAndPseudoCriticalEdges(n: number, edges: number[][]): number[][] {\n    const e = edges.length;\n    const indexedEdges = edges.map((edge, i) => [edge[0], edge[1], edge[2], i]);\n    indexedEdges.sort((a, b) => a[2] - b[2]);\n\n    const find = (parent: number[], x: number): number => {\n        if (parent[x] !== x) parent[x] = find(parent, parent[x]);\n        return parent[x];\n    };\n\n    const unionSets = (parent: number[], rank: number[], x: number, y: number): void => {\n        if (rank[x] < rank[y]) parent[x] = y;\n        else if (rank[x] > rank[y]) parent[y] = x;\n        else { parent[y] = x; rank[x]++; }\n    };\n\n    const buildMST = (excludeIdx: number, includeIdx: number): number => {\n        const parent = Array.from({length: n}, (_, i) => i);\n        const rank = new Array(n).fill(0);\n        let weight = 0, edgesUsed = 0;\n\n        if (includeIdx >= 0) {\n            weight += indexedEdges[includeIdx][2];\n            unionSets(parent, rank, find(parent, indexedEdges[includeIdx][0]),\n                find(parent, indexedEdges[includeIdx][1]));\n            edgesUsed++;\n        }\n\n        for (let i = 0; i < e; i++) {\n            if (i === excludeIdx || i === includeIdx) continue;\n            const u = indexedEdges[i][0], v = indexedEdges[i][1], w = indexedEdges[i][2];\n            const pu = find(parent, u), pv = find(parent, v);\n            if (pu !== pv) {\n                unionSets(parent, rank, pu, pv);\n                weight += w;\n                if (++edgesUsed === n - 1) break;\n            }\n        }\n\n        return edgesUsed === n - 1 ? weight : Infinity;\n    };\n\n    const baselineWeight = buildMST(-1, -1);\n\n    const critical: number[] = [], pseudoCritical: number[] = [];\n    for (let i = 0; i < e; i++) {\n        const weightWithout = buildMST(i, -1);\n        if (weightWithout > baselineWeight) {\n            critical.push(indexedEdges[i][3]);\n        } else {\n            const weightWith = buildMST(-1, i);\n            if (weightWith === baselineWeight) {\n                pseudoCritical.push(indexedEdges[i][3]);\n            }\n        }\n    }\n\n    return [critical, pseudoCritical];\n}",
