function generateFloydWarshallSteps(__inputArg: any): any[] {
  
  return (function(t: any) {
let e=t.matrix,i=e.length;if(0===i){let t=new StepRecorder({dist:[]},{});return t.record("return_result","Empty matrix"),t.getSteps()}let a=e.map(t=>[...t]),l=new StepRecorder({dist:a.map(t=>[...t]),k:null,i:null,j:null,intermediateNode:null},{});l.add_new_visual("matrix",{type:"distanceMatrix",data:a.map(t=>[...t]),highlightCell:null,highlightRow:null,highlightCol:null}),l.record("init","Initialize distance matrix with direct edge weights (∞ = no direct edge)");for(let t=0;t<i;t++){l.update_variable("k",t),l.update_variable("intermediateNode",t),l.update_visual("matrix",{type:"distanceMatrix",data:a.map(t=>[...t]),highlightCell:null,highlightRow:null,highlightCol:t,intermediateNode:t}),l.record("outer_loop",`Consider vertex ${t} as intermediate node`);for(let e=0;e<i;e++){l.update_variable("i",e);for(let r=0;r<i;r++)if(l.update_variable("j",r),l.update_visual("matrix",{type:"distanceMatrix",data:a.map(t=>[...t]),highlightCell:[e,r],highlightRow:e,highlightCol:r,intermediateNode:t,pathCells:[[e,t],[t,r]]}),l.record("check_path",`Check if path ${e} → ${t} → ${r} is shorter than ${e} → ${r}`),a[e][t]!==1/0&&a[t][r]!==1/0){let i=a[e][t]+a[t][r];if(i<a[e][r]){let n=a[e][r];a[e][r]=i,l.update_variable("dist",a.map(t=>[...t])),l.update_visual("matrix",{type:"distanceMatrix",data:a.map(t=>[...t]),highlightCell:[e,r],highlightRow:e,highlightCol:r,intermediateNode:t,pathCells:[[e,t],[t,r]],updatedCell:[e,r]}),l.set_conditionals([{key:"update_dist",result:!0}]),l.record("update_dist",`Update: dist[${e}][${r}] = ${n===1/0?"∞":n} → ${i} (via ${t})`)}else l.set_conditionals([{key:"no_update",result:!1}]),l.record("no_update",`No update: ${a[e][t]} + ${a[t][r]} = ${i} ≥ ${a[e][r]===1/0?"∞":a[e][r]}`)}else l.set_conditionals([{key:"no_update",result:!1}]),l.record("no_update",`Skip: path through ${t} not possible (∞ in path)`)}l.record("iteration_complete",`Completed considering vertex ${t} as intermediate`)}let n=!1;for(let t=0;t<i;t++)if(a[t][t]<0){n=!0;break}return l.update_visual("matrix",{type:"distanceMatrix",data:a.map(t=>[...t]),highlightCell:null,highlightRow:null,highlightCol:null,intermediateNode:null,complete:!0}),n?l.record("return_result","Floyd-Warshall complete! Warning: Negative cycle detected in the graph."):l.record("return_result","Floyd-Warshall complete! All-pairs shortest paths computed."),l.getSteps()
  })(__inputArg);
}

export function FloydWarshallProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: FloydWarshallTemplates,
      generateSteps: (t: any) => {
        const recorded = generateFloydWarshallSteps(t) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Floyd-Warshall Algorithm"
      slug="floyd-warshall"
      approaches={approaches}
      presets={FloydWarshallPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

