    "code": "public int[] KosarajuSCC(int n, int[][] edges) {\n    var graph = new List<List<int>>();\n    var trans = new List<List<int>>();\n    for (int i = 0; i < n; i++) {\n        graph.Add(new List<int>());\n        trans.Add(new List<int>());\n    }\n    foreach (var e in edges) {\n        graph[e[0]].Add(e[1]);\n        trans[e[1]].Add(e[0]);\n    }\n\n    var visited = new bool[n];\n    var stack = new Stack<int>();\n\n    // Pass 1\n    void Dfs1(int node) {\n        visited[node] = true;\n        foreach (var nb in graph[node]) {\n            if (!visited[nb]) Dfs1(nb);\n        }\n        stack.Push(node);\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) Dfs1(i);\n    }\n\n    // Pass 2\n    visited = new bool[n];\n    var components = new int[n];\n    Array.Fill(components, -1);\n    int compId = 0;\n\n    void Dfs2(int node, int comp) {\n        visited[node] = true;\n        components[node] = comp;\n        foreach (var nb in trans[node]) {\n            if (!visited[nb]) Dfs2(nb, comp);\n        }\n    }\n\n    while (stack.Count > 0) {\n        int node = stack.Pop();\n        if (!visited[node]) {\n            Dfs2(node, compId);\n            compId++;\n        }\n    }\n\n    return components;\n}",
