function generateKruskalMstSteps(__inputArg: any): any[] {
  
  return (function(e: any) {
let{n:t,edges:i}=e,o=new StepRecorder({n:t,edges:i,sortedEdges:null,mstEdges:[],mstWeight:null,currentEdge:null,currentEdgeIndex:null,edgesInMST:null},{});o.record("start",`Given a graph with ${t} vertices and ${i.length} edges. Find the Minimum Spanning Tree using Kruskal's algorithm.`);let s=[...i].sort((e,t)=>e.weight-t.weight);o.update_variable("sortedEdges",s),o.record("sort_edges",`Sort all edges by weight in ascending order: [${s.map(e=>`(${e.u}-${e.v}:${e.weight})`).join(", ")}]`);let a=new r.n(t,!1),d=Array.from({length:t},(e,t)=>t);r.u.initializeUnionFind(o,d,!1),o.update_variable("mstWeight",0),o.update_variable("edgesInMST",0),o.record("initialize",`Initialize Union-Find for ${t} vertices (0 to ${t-1}). MST starts empty with weight = 0.`);let l=[],g=0;for(let e=0;e<s.length;e++){let i=s[e],{u:n,v:u,weight:h}=i;o.update_variable("currentEdge",i),o.update_variable("currentEdgeIndex",e),r.u.highlightNode(o,n,"visiting"),r.u.highlightNode(o,u,"visiting"),o.record("process_edge",`Process edge ${e+1}/${s.length}: (${n} - ${u}) with weight ${h}`);let c=a.find(n),p=a.find(u);if(c!==n&&r.u.highlightNode(o,c,"active"),p!==u&&p!==c&&r.u.highlightNode(o,p,"active"),o.record("find_roots",`Find roots: find(${n}) = ${c}, find(${u}) = ${p}`),c===p)o.add_conditional("if_different_components",!1),r.u.highlightNode(o,n,"conflict"),r.u.highlightNode(o,u,"conflict"),o.record("skip_edge",`Vertices ${n} and ${u} are already connected (same root = ${c}). Adding this edge would create a cycle. Skip.`);else{o.add_conditional("if_different_components",!0),a.union(n,u),l.push(i),g+=h,o.update_variable("mstEdges",[...l]),o.update_variable("mstWeight",g),o.update_variable("edgesInMST",l.length);let e=a.find(c),s=a.find(p);if(e!==c&&(r.u.updateParent(o,c,e),r.u.updateSize(o,e,a.getSize(e))),s!==p&&s!==e&&(r.u.updateParent(o,p,e),r.u.updateSize(o,e,a.getSize(e))),d.forEach(e=>{let t=a.getParent(e),i=o.get_visual(`uf_${e}`);i&&"unionFindNode"===i.type&&i.parent!==t&&(r.u.updateParent(o,e,t),r.u.updateSize(o,e,a.getSize(e)))}),r.u.highlightNode(o,n,"highlight"),r.u.highlightNode(o,u,"highlight"),o.record("add_edge",`Add edge (${n} - ${u}) to MST. MST now has ${l.length} edge(s) with total weight = ${g}`),l.length===t-1)return r.u.resetAllStates(o,d),d.forEach(e=>{r.u.highlightNode(o,e,"highlight")}),o.record("mst_complete",`MST is complete! Found ${t-1} edges connecting all ${t} vertices.`),o.record("complete",`Kruskal's algorithm complete! Minimum Spanning Tree weight = ${g}`),o.steps}r.u.resetAllStates(o,d)}return o.record("complete",`Algorithm complete. MST has ${l.length} edges with total weight = ${g}. (Graph may be disconnected)`),o.steps
  })(__inputArg);
}

export function KruskalMstProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: KruskalMstTemplates,
      generateSteps: (e: any) => {
        const recorded = generateKruskalMstSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Kruskal's MST Algorithm"
      slug="kruskal-mst"
      approaches={approaches}
      presets={KruskalMstPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

