    "language": "csharp",
    "code": "public class Solution {\n    int[][] directions = new int[][] {\n        new int[] {0, 1}, new int[] {0, -1}, new int[] {1, 0}, new int[] {-1, 0}\n    };\n\n    public int LargestIsland(int[][] grid) {\n        int n = grid.Length;\n        Dictionary<int, int> islandSize = new Dictionary<int, int>();\n        int islandId = 2;\n\n        // Phase 1: Label each island with a unique ID and compute its size\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == 1) {\n                    int size = Dfs(grid, i, j, islandId);\n                    islandSize[islandId] = size;\n                    islandId++;\n                }\n            }\n        }\n\n        // If there are no islands at all, flipping one cell gives size 1\n        if (islandSize.Count == 0) return 1;\n\n        int maxSize = 0;\n        bool hasZero = false;\n\n        // Phase 2: For each 0 cell, check neighboring islands\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == 0) {\n                    hasZero = true;\n                    HashSet<int> neighborIslands = new HashSet<int>();\n                    foreach (var dir in directions) {\n                        int nr = i + dir[0], nc = j + dir[1];\n                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] > 1) {\n                            neighborIslands.Add(grid[nr][nc]);\n                        }\n                    }\n                    int size = 1; // the flipped cell itself\n                    foreach (int id in neighborIslands) {\n                        size += islandSize[id];\n                    }\n                    maxSize = Math.Max(maxSize, size);\n                }\n            }\n        }\n\n        // If no zero exists, the whole grid is one island\n        return hasZero ? maxSize : n * n;\n    }\n\n    private int Dfs(int[][] grid, int r, int c, int islandId) {\n        int n = grid.Length;\n        if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] != 1) {\n            return 0;\n        }\n        grid[r][c] = islandId;\n        int size = 1;\n        foreach (var dir in directions) {\n            size += Dfs(grid, r + dir[0], c + dir[1], islandId);\n        }\n        return size;\n    }\n}",
