    "code": "func largestIsland(grid [][]int) int {\n    n := len(grid)\n    directions := [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}\n    islandSize := map[int]int{}\n    islandId := 2\n\n    var dfs func(r, c, id int) int\n    dfs = func(r, c, id int) int {\n        if r < 0 || r >= n || c < 0 || c >= n || grid[r][c] != 1 {\n            return 0\n        }\n        grid[r][c] = id\n        size := 1\n        for _, dir := range directions {\n            size += dfs(r+dir[0], c+dir[1], id)\n        }\n        return size\n    }\n\n    // Phase 1: Label each island with a unique ID and compute its size\n    for i := 0; i < n; i++ {\n        for j := 0; j < n; j++ {\n            if grid[i][j] == 1 {\n                islandSize[islandId] = dfs(i, j, islandId)\n                islandId++\n            }\n        }\n    }\n\n    // If there are no islands at all, flipping one cell gives size 1\n    if len(islandSize) == 0 {\n        return 1\n    }\n\n    maxSize := 0\n    hasZero := false\n\n    // Phase 2: For each 0 cell, check neighboring islands\n    for i := 0; i < n; i++ {\n        for j := 0; j < n; j++ {\n            if grid[i][j] == 0 {\n                hasZero = true\n                neighborIslands := map[int]bool{}\n                for _, dir := range directions {\n                    nr, nc := i+dir[0], j+dir[1]\n                    if nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] > 1 {\n                        neighborIslands[grid[nr][nc]] = true\n                    }\n                }\n                size := 1 // the flipped cell itself\n                for id := range neighborIslands {\n                    size += islandSize[id]\n                }\n                if size > maxSize {\n                    maxSize = size\n                }\n            }\n        }\n    }\n\n    // If no zero exists, the whole grid is one island\n    if !hasZero {\n        return n * n\n    }\n    return maxSize\n}",
