    "language": "csharp",
    "code": "public class Solution {\n    public int MaxStability(int n, int[][] edges, int k) {\n        var mustEdges = new List<int[]>();\n        var optionalEdges = new List<int[]>();\n\n        foreach (var e in edges) {\n            if (e[3] == 1) mustEdges.Add(e);\n            else optionalEdges.Add(e);\n        }\n\n        if (mustEdges.Count > n - 1) return -1;\n\n        int[] baseParent = new int[n];\n        for (int i = 0; i < n; i++) baseParent[i] = i;\n        int baseCount = 0;\n        int mustMin = int.MaxValue;\n\n        foreach (var e in mustEdges) {\n            int pu = Find(baseParent, e[0]);\n            int pv = Find(baseParent, e[1]);\n            if (pu == pv) return -1;\n            baseParent[pu] = pv;\n            baseCount++;\n            mustMin = Math.Min(mustMin, e[2]);\n        }\n\n        int best = 0;\n        int m = optionalEdges.Count;\n\n        for (int mask = 0; mask < (1 << m); mask++) {\n            if (CountBits(mask) > k) continue;\n\n            int[] parent = (int[])baseParent.Clone();\n            int count = baseCount;\n\n            int[][] modified = new int[m][];\n            for (int i = 0; i < m; i++) {\n                int w = ((mask >> i) & 1) == 1\n                    ? optionalEdges[i][2] * 2\n                    : optionalEdges[i][2];\n                modified[i] = new int[] { optionalEdges[i][0], optionalEdges[i][1], w };\n            }\n            Array.Sort(modified, (a, b) => b[2] - a[2]);\n\n            int minWeight = mustMin;\n            foreach (var edge in modified) {\n                int pu = Find(parent, edge[0]);\n                int pv = Find(parent, edge[1]);\n                if (pu != pv) {\n                    parent[pu] = pv;\n                    minWeight = Math.Min(minWeight, edge[2]);\n                    if (++count == n - 1) break;\n                }\n            }\n\n            if (count == n - 1) best = Math.Max(best, minWeight);\n        }\n\n        return best == 0 && baseCount < n - 1 ? -1 : best;\n    }\n\n    private int Find(int[] parent, int x) {\n        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }\n        return x;\n    }\n\n    private int CountBits(int n) {\n        int c = 0;\n        while (n > 0) { c += n & 1; n >>= 1; }\n        return c;\n    }\n}",
