    "code": "function maxStability(n: number, edges: number[][], k: number): number {\n    const find = (parent: number[], x: number): number => {\n        while (parent[x] !== x) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    };\n\n    const mustEdges: number[][] = [];\n    const optionalEdges: number[][] = [];\n    for (const e of edges) {\n        if (e[3] === 1) mustEdges.push(e);\n        else optionalEdges.push(e);\n    }\n\n    if (mustEdges.length > n - 1) return -1;\n\n    const baseParent = Array.from({length: n}, (_, i) => i);\n    let baseCount = 0;\n    let mustMin = Infinity;\n\n    for (const e of mustEdges) {\n        const pu = find(baseParent, e[0]);\n        const pv = find(baseParent, e[1]);\n        if (pu === pv) return -1;\n        baseParent[pu] = pv;\n        baseCount++;\n        mustMin = Math.min(mustMin, e[2]);\n    }\n\n    let best = 0;\n    const m = optionalEdges.length;\n\n    for (let mask = 0; mask < (1 << m); mask++) {\n        let bitCount = 0, tmp = mask;\n        while (tmp > 0) { bitCount += tmp & 1; tmp >>= 1; }\n        if (bitCount > k) continue;\n\n        const parent = baseParent.slice();\n        let count = baseCount;\n\n        const modified: number[][] = [];\n        for (let i = 0; i < m; i++) {\n            const w = ((mask >> i) & 1) === 1\n                ? optionalEdges[i][2] * 2\n                : optionalEdges[i][2];\n            modified.push([optionalEdges[i][0], optionalEdges[i][1], w]);\n        }\n        modified.sort((a, b) => b[2] - a[2]);\n\n        let minWeight = mustMin;\n        for (const edge of modified) {\n            const pu = find(parent, edge[0]);\n            const pv = find(parent, edge[1]);\n            if (pu !== pv) {\n                parent[pu] = pv;\n                minWeight = Math.min(minWeight, edge[2]);\n                count++;\n                if (count === n - 1) break;\n            }\n        }\n\n        if (count === n - 1) best = Math.max(best, minWeight);\n    }\n\n    return best === 0 && baseCount < n - 1 ? -1 : best;\n}",
