    "language": "java",
    "code": "class Solution {\n    private int m, n;\n    private int[][] heights;\n    private int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};\n\n    public List<List<Integer>> pacificAtlantic(int[][] heights) {\n        this.heights = heights;\n        m = heights.length;\n        n = heights[0].length;\n\n        boolean[][] pacific = new boolean[m][n];\n        boolean[][] atlantic = new boolean[m][n];\n\n        // DFS from Pacific border (top row + left column)\n        for (int c = 0; c < n; c++) dfs(0, c, pacific);\n        for (int r = 0; r < m; r++) dfs(r, 0, pacific);\n\n        // DFS from Atlantic border (bottom row + right column)\n        for (int c = 0; c < n; c++) dfs(m - 1, c, atlantic);\n        for (int r = 0; r < m; r++) dfs(r, n - 1, atlantic);\n\n        // Collect cells reachable from both oceans\n        List<List<Integer>> result = new ArrayList<>();\n        for (int r = 0; r < m; r++) {\n            for (int c = 0; c < n; c++) {\n                if (pacific[r][c] && atlantic[r][c]) {\n                    result.add(List.of(r, c));\n                }\n            }\n        }\n        return result;\n    }\n\n    private void dfs(int r, int c, boolean[][] reachable) {\n        reachable[r][c] = true;\n        for (int[] dir : directions) {\n            int nr = r + dir[0], nc = c + dir[1];\n            // Move to neighbor if it has equal or greater height (reverse flow)\n            if (nr >= 0 && nr < m && nc >= 0 && nc < n\n                    && !reachable[nr][nc] && heights[nr][nc] >= heights[r][c]) {\n                dfs(nr, nc, reachable);\n            }\n        }\n    }\n}",
