    "language": "csharp",
    "code": "public class Solution {\n    private int m, n;\n    private int[][] directions = new int[][] {\n        new int[] {0, 1}, new int[] {0, -1},\n        new int[] {1, 0}, new int[] {-1, 0}\n    };\n\n    public IList<IList<int>> PacificAtlantic(int[][] heights) {\n        m = heights.Length;\n        n = heights[0].Length;\n        bool[,] pacific = new bool[m, n];\n        bool[,] atlantic = new bool[m, n];\n\n        // DFS from Pacific border (top row + left column)\n        for (int c = 0; c < n; c++) Dfs(heights, 0, c, pacific);\n        for (int r = 0; r < m; r++) Dfs(heights, r, 0, pacific);\n\n        // DFS from Atlantic border (bottom row + right column)\n        for (int c = 0; c < n; c++) Dfs(heights, m - 1, c, atlantic);\n        for (int r = 0; r < m; r++) Dfs(heights, r, n - 1, atlantic);\n\n        // Collect cells reachable from both oceans\n        var result = new List<IList<int>>();\n        for (int r = 0; r < m; r++) {\n            for (int c = 0; c < n; c++) {\n                if (pacific[r, c] && atlantic[r, c]) {\n                    result.Add(new List<int> { r, c });\n                }\n            }\n        }\n        return result;\n    }\n\n    private void Dfs(int[][] heights, int r, int c, bool[,] reachable) {\n        reachable[r, c] = true;\n        foreach (var dir in directions) {\n            int nr = r + dir[0], nc = c + dir[1];\n            // Move to neighbor if it has equal or greater height (reverse flow)\n            if (nr >= 0 && nr < m && nc >= 0 && nc < n\n                    && !reachable[nr, nc] && heights[nr][nc] >= heights[r][c]) {\n                Dfs(heights, nr, nc, reachable);\n            }\n        }\n    }\n}",
