    "language": "go",
    "code": "func pacificAtlantic(heights [][]int) [][]int {\n    m, n := len(heights), len(heights[0])\n    directions := [4][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}\n\n    makeGrid := func() [][]bool {\n        grid := make([][]bool, m)\n        for i := range grid {\n            grid[i] = make([]bool, n)\n        }\n        return grid\n    }\n\n    pacific := makeGrid()\n    atlantic := makeGrid()\n\n    var dfs func(r, c int, reachable [][]bool)\n    dfs = func(r, c int, reachable [][]bool) {\n        reachable[r][c] = true\n        for _, dir := range directions {\n            nr, nc := r+dir[0], c+dir[1]\n            // Move to neighbor if it has equal or greater height (reverse flow)\n            if nr >= 0 && nr < m && nc >= 0 && nc < n &&\n                !reachable[nr][nc] && heights[nr][nc] >= heights[r][c] {\n                dfs(nr, nc, reachable)\n            }\n        }\n    }\n\n    // DFS from Pacific border (top row + left column)\n    for c := 0; c < n; c++ {\n        dfs(0, c, pacific)\n    }\n    for r := 0; r < m; r++ {\n        dfs(r, 0, pacific)\n    }\n\n    // DFS from Atlantic border (bottom row + right column)\n    for c := 0; c < n; c++ {\n        dfs(m-1, c, atlantic)\n    }\n    for r := 0; r < m; r++ {\n        dfs(r, n-1, atlantic)\n    }\n\n    // Collect cells reachable from both oceans\n    result := [][]int{}\n    for r := 0; r < m; r++ {\n        for c := 0; c < n; c++ {\n            if pacific[r][c] && atlantic[r][c] {\n                result = append(result, []int{r, c})\n            }\n        }\n    }\n    return result\n}",
