    "code": "function pacificAtlantic(heights: number[][]): number[][] {\n    const m = heights.length, n = heights[0].length;\n    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];\n\n    const makeGrid = (): boolean[][] => {\n        return Array.from({length: m}, () => new Array(n).fill(false));\n    };\n\n    const pacific = makeGrid();\n    const atlantic = makeGrid();\n\n    function dfs(r: number, c: number, reachable: boolean[][]): void {\n        reachable[r][c] = true;\n        for (const [dr, dc] of directions) {\n            const nr = r + dr, nc = c + dc;\n            // Move to neighbor if it has equal or greater height (reverse flow)\n            if (nr >= 0 && nr < m && nc >= 0 && nc < n\n                    && !reachable[nr][nc] && heights[nr][nc] >= heights[r][c]) {\n                dfs(nr, nc, reachable);\n            }\n        }\n    }\n\n    // DFS from Pacific border (top row + left column)\n    for (let c = 0; c < n; c++) dfs(0, c, pacific);\n    for (let r = 0; r < m; r++) dfs(r, 0, pacific);\n\n    // DFS from Atlantic border (bottom row + right column)\n    for (let c = 0; c < n; c++) dfs(m - 1, c, atlantic);\n    for (let r = 0; r < m; r++) dfs(r, n - 1, atlantic);\n\n    // Collect cells reachable from both oceans\n    const result: number[][] = [];\n    for (let r = 0; r < m; r++) {\n        for (let c = 0; c < n; c++) {\n            if (pacific[r][c] && atlantic[r][c]) {\n                result.push([r, c]);\n            }\n        }\n    }\n    return result;\n}",
