function generatePrimMstSteps(__inputArg: any): any[] {
  
  return (function(e: any) {
let t=e.n,i=e.edges;if(0===t){let e=new StepRecorder({n:0,in_mst:[],total_weight:0},{});return e.record("complete","Empty graph - no MST possible"),e.getSteps()}let r=Array.from({length:t},()=>[]);for(let[e,t,n]of i)r[e].push([n,t]),r[t].push([n,e]);let a={};for(let e=0;e<t;e++)a[`node_${e}`]={type:"graphNode",nodeId:e,value:e,label:String(e),state:"standard"};let o=new Set;for(let[e,t,n]of i){let i=e<t?`${e}_${t}`:`${t}_${e}`;o.has(i)||(o.add(i),a[`edge_${i}`]={type:"graphEdge",from:Math.min(e,t),to:Math.max(e,t),weight:n,directed:!1,state:"standard"})}let s=Array(t).fill(!1),l=new StepRecorder({n:t,in_mst:s.map(e=>e?"T":"F"),total_weight:0,currentNode:null},a);l.record("-","Start: Prim's MST Algorithm. Begin from node 0."),l.record("build_graph",`Build adjacency list from ${i.length} edges for ${t} nodes.`);let d=[[0,0,-1]];l.update_visual("node_0",{type:"graphNode",nodeId:0,value:0,label:"0",state:"visiting"}),l.record("init_heap","Initialize min-heap with [(0, node 0)]. Start from node 0.");let h=[],p=0;for(;d.length>0;){let e=0===d.length?null:(d.sort((e,t)=>e[0]-t[0]),d.shift());if(!e)break;let[t,i,n]=e;if(s[i]||l.update_visual(`node_${i}`,{type:"graphNode",nodeId:i,value:i,label:String(i),state:"highlight"}),l.update_variable("currentNode",i),l.record("extract_min",`Extract min from heap: node ${i} with weight ${t}${-1!==n?` (from node ${n})`:""}`),s[i]){l.set_conditionals([{key:"skip_in_mst",result:!0}]),l.record("skip_in_mst",`Skip node ${i} - already in MST`);continue}if(s[i]=!0,p+=t,l.update_variable("in_mst",s.map(e=>e?"T":"F")),l.update_variable("total_weight",p),l.update_visual(`node_${i}`,{type:"graphNode",nodeId:i,value:i,label:String(i),state:"visited"}),l.set_conditionals([{key:"skip_in_mst",result:!1}]),-1!==n){h.push([n,i,t]);let e=n<i?`${n}_${i}`:`${i}_${n}`;l.update_visual(`edge_${e}`,{type:"graphEdge",from:Math.min(n,i),to:Math.max(n,i),weight:t,directed:!1,state:"active"}),l.record("add_to_mst",`Add node ${i} to MST via edge (${n}, ${i}) with weight ${t}. Total weight: ${p}`)}else l.record("add_to_mst",`Add starting node ${i} to MST. Total weight: ${p}`);for(let[e,t]of r[i]){if(s[t])continue;let n=i<t?`${i}_${t}`:`${t}_${i}`;l.update_visual(`edge_${n}`,{type:"graphEdge",from:Math.min(i,t),to:Math.max(i,t),weight:e,directed:!1,state:"active"}),s[t]||l.update_visual(`node_${t}`,{type:"graphNode",nodeId:t,value:t,label:String(t),state:"visiting"}),d.push([e,t,i]),l.record("push_neighbor",`Push neighbor ${t} with edge weight ${e} to heap`),l.update_visual(`edge_${n}`,{type:"graphEdge",from:Math.min(i,t),to:Math.max(i,t),weight:e,directed:!1,state:"standard"})}}l.update_variable("currentNode",null);let g=h.map(([e,t,i])=>`(${e}-${t}: ${i})`).join(", ");return l.record("complete",`Prim's MST complete! MST edges: ${g}. Total weight: ${p}`),l.getSteps()
  })(__inputArg);
}

export function PrimMstProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: PrimMstTemplates,
      generateSteps: (e: any) => {
        const recorded = generatePrimMstSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Prim's MST Algorithm"
      slug="prim-mst"
      approaches={approaches}
      presets={PrimMstPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

